    def clamp(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pair(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def as_points(v):
        out = []
        if isinstance(v, list):
            for item in v:
                if isinstance(item, (list, tuple)) and len(item) >= 2:
                    out.append((item[0], item[1]))
        return out

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp(b[0] - a[0]), clamp(b[1] - a[1])]

    def step_away(a, b):
        return [clamp(a[0] - b[0]), clamp(a[1] - b[1])]

    def in_bounds(p, w, h):
        return (w is None or h is None or (0 <= p[0] < w and 0 <= p[1] < h))

    env = observation.get("environment_name", "") or ""
    role = observation.get("self_role", "") or ""
    sx, sy = pair(observation.get("self_position"))
    ox, oy = pair(observation.get("opponent_position"), (sx, sy))
    me = (sx, sy)
    opp = (ox, oy)

    w = observation.get("grid_width")
    h = observation.get("grid_height")
    if not isinstance(w, int) or w <= 0:
        w = None
    if not isinstance(h, int) or h <= 0:
        h = None

    resources = as_points(observation.get("resources"))
    unclaimed = as_points(observation.get("unclaimed_cells"))
    opp_terr = as_points(observation.get("opponent_territory"))
    own_terr = as_points(observation.get("own_territory"))
    hazards = as_points(observation.get("hazards"))
    enemies = as_points(observation.get("enemies"))

    def safe_moves():
        moves = [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]
        if w is None or h is None:
            return moves
        out = []
        for m in moves:
            p = (me[0] + m[0], me[1] + m[1])
            if in_bounds(p, w, h):
                out.append(m)
        return out or [[0, 0]]

    def score_cell(c):
        d_me = manhattan(me, c)
        d_opp = manhattan(opp, c)
        return d_me * 2 - d_opp

    def choose_from(targets):
        if not targets:
            return [0, 0]
        t = min(targets, key=lambda c: score_cell(c))
        return step_toward(me, t)

    # Pursuit / evasion
    if env == "pursuit_evasion":
        if role == "pursuer":
            if enemies:
                target = min(enemies, key=lambda c: manhattan(me, c))
                return step_toward(me, target)
            return step_toward(me, opp)
        # evader: maximize distance from opponent, prefer boundary/corners
        candidates = []
        if w is not None and h is not None:
            candidates = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        else:
            candidates = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        best = max(candidates, key=lambda c: manhattan(c, opp))
        return step_toward(me, best)

    # Territory control
    if env == "territory_control":
        if unclaimed:
            return choose_from(unclaimed)
        if opp_terr:
            return choose_from(opp_terr)
        if own_terr:
            if w is not None and h is not None:
                center = ((w - 1) // 2, (h - 1) // 2)
                return step_toward(me, center)
            return choose_from(own_terr)
        if w is not None and h is not None:
            center = ((w - 1) // 2, (h - 1) // 2)
            return step_toward(me, center)
        return [0, 0]

    # Resource collection
    if resources:
        # Prefer closer resources, but avoid ones contested by opponent.
        best = None
        best_score = None
        for r in resources:
            d_me = manhattan(me, r)
            d_opp = manhattan(opp, r)
            contested = 1 if d_opp <= d_me else 0
            hazard_pen = 2 if r in hazards else 0
            score = d_me + contested * 3 + hazard_pen
            if best is None or score < best_score:
                best = r
                best_score = score
        return step_toward(me, best)

    # Generic fallback: move away if threatened, else toward opponent/center
    if opp != me:
        if manhattan(me, opp) <= 2:
            mv = step_away(me, opp)
            if mv != [0, 0]:
                return mv
        return step_toward(me, opp)

    if own_terr and w is not None and h is not None:
        center = ((w - 1) // 2, (h - 1) // 2)
        return step_toward(me, center)

    return [0, 0]

